// src/windows-ink.ps1
var windows_ink_default = `# Local Windows Ink recognizer. Only structured stroke data arrives over stdin.
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::InputEncoding=[Text.UTF8Encoding]::new()
[Console]::OutputEncoding=[Text.UTF8Encoding]::new()
try {
    Add-Type -AssemblyName System.Runtime.WindowsRuntime
    $null=[Windows.UI.Input.Inking.InkStrokeBuilder,Windows.UI.Input.Inking,ContentType=WindowsRuntime]
    $null=[Windows.UI.Input.Inking.InkStrokeContainer,Windows.UI.Input.Inking,ContentType=WindowsRuntime]
    $null=[Windows.UI.Input.Inking.InkRecognizerContainer,Windows.UI.Input.Inking,ContentType=WindowsRuntime]
    $null=[Windows.UI.Input.Inking.InkRecognitionResult,Windows.UI.Input.Inking,ContentType=WindowsRuntime]
    $builder=[Windows.UI.Input.Inking.InkStrokeBuilder]::new()
    # Resolve the projected Point type through its API signature. It is not a
    # separately activatable WinRT class on .NET Framework / Windows PowerShell.
    $pointType=($builder.GetType().GetMethods()|Where-Object {$_.Name -eq 'CreateStroke'}).GetParameters()[0].ParameterType.GenericTypeArguments[0]
    $listType=[System.Collections.Generic.List[object]].GetGenericTypeDefinition().MakeGenericType($pointType)
    $recognizer=[Windows.UI.Input.Inking.InkRecognizerContainer]::new()
    $installed=@($recognizer.GetRecognizers())
    $selectedLanguage=''
    $asTask=[System.WindowsRuntimeSystemExtensions].GetMethods()|Where-Object {$_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.IsGenericMethod}|Select-Object -First 1
    $resultType=[System.Collections.Generic.IReadOnlyList[Windows.UI.Input.Inking.InkRecognitionResult]]
    $await=$asTask.MakeGenericMethod($resultType)
} catch { [Console]::WriteLine((@{id=0;error=$_.Exception.Message}|ConvertTo-Json -Compress)); exit 1 }
while ($null -ne ($line=[Console]::ReadLine())) {
    $request=$null
    try {
        if ($line.Length -gt 8000000) { throw 'Demasiadas muestras.' }
        $request=$line|ConvertFrom-Json
        if (@($request.strokes).Count -gt 128) { throw 'Demasiados trazos.' }
        $language=[string]$request.language
        if (-not $language) { $language='es' }
        if ($language -ne 'es' -and $language -ne 'en') { throw 'Idioma de escritura inv\xE1lido.' }
        if ($selectedLanguage -ne $language) {
            $pattern=if ($language -eq 'en') { 'English|Ingl[e\xE9]s' } else { 'Spanish|Espa[\xF1n]ol' }
            $available=@($installed|Where-Object {$_.Name -match $pattern})
            if ($available.Count -eq 0) {
                $label=if ($language -eq 'en') { 'ingl\xE9s' } else { 'espa\xF1ol' }
                throw "Falta el reconocimiento de escritura en $label. En Configuraci\xF3n de Windows > Hora e idioma > Idioma y regi\xF3n > Opciones del idioma, instala Escritura a mano. Tus trazos se conservan."
            }
            $recognizer.SetDefaultRecognizer($available[0])
            $selectedLanguage=$language
        }
        $container=[Windows.UI.Input.Inking.InkStrokeContainer]::new()
        $ids=@{}
        foreach ($source in $request.strokes) {
            $points=[Activator]::CreateInstance($listType)
            foreach ($sample in $source.points) {
                $point=[Activator]::CreateInstance($pointType)
                $point.X=[double]$sample[0];$point.Y=[double]$sample[1]
                $points.Add($point)
            }
            if ($points.Count -lt 2) { continue }
            $stroke=$builder.CreateStroke($points)
            $ids[[uint32]$stroke.Id]=[int]$source.index
            $container.AddStroke($stroke)
        }
        $operation=$recognizer.RecognizeAsync($container,[Windows.UI.Input.Inking.InkRecognitionTarget]::All)
        $task=$await.Invoke($null,@($operation))
        $task.Wait()
        $words=@($task.Result|ForEach-Object {
            $text=@($_.GetTextCandidates())[0]
            $indices=@($_.GetStrokes()|ForEach-Object { $ids[[uint32]$_.Id] })
            if ($text -and $indices.Count) { @{text=$text;strokes=$indices} }
        })
        [Console]::WriteLine((@{id=$request.id;words=$words}|ConvertTo-Json -Compress -Depth 8))
    } catch { [Console]::WriteLine((@{id=$request.id;error=$_.Exception.Message}|ConvertTo-Json -Compress)) }
}
`;

