var WindowsInkRecognizer = class {
  process;
  pending = /* @__PURE__ */ new Map();
  serial = 0;
  disposed = false;
  start() {
    if (this.disposed) throw new Error("El reconocedor est\xE1 cerrado.");
    if (this.process) return;
    const { spawn } = require("node:child_process");
    const root = process.env.SystemRoot || "C:\\Windows";
    const child = spawn(
      `${root}\\System32\\WindowsPowerShell\\v1.0\\powershell.exe`,
      [
        "-NoLogo",
        "-NoProfile",
        "-NonInteractive",
        "-EncodedCommand",
        Buffer.from(windows_ink_default, "utf16le").toString("base64")
      ],
      { windowsHide: true, stdio: "pipe" }
    );
    this.process = child;
    let buffer = "";
    child.stdout.setEncoding("utf8");
    child.stdout.on("data", (chunk) => {
      buffer += chunk;
      if (buffer.length > 2e6) {
        this.fail(new Error("Respuesta de reconocimiento demasiado grande."));
        return;
      }
      let newline;
      while ((newline = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, newline).trim();
        buffer = buffer.slice(newline + 1);
        if (!line) continue;
        try {
          const result = JSON.parse(line);
          if (result.id === 0 && result.error) {
            this.fail(new Error(result.error));
            return;
          }
          const request = this.pending.get(result.id);
          if (!request) continue;
          clearTimeout(request.timer);
          this.pending.delete(result.id);
          if (result.error) request.reject(new Error(result.error));
          else if (Array.isArray(result.words) && result.words.length <= 128 && result.words.every(
            (w3) => typeof w3.text === "string" && w3.text.length <= 500 && Array.isArray(w3.strokes) && w3.strokes.every(Number.isSafeInteger)
          ))
            request.resolve(result.words);
          else
            request.reject(new Error("Respuesta de reconocimiento inv\xE1lida."));
        } catch {
          this.fail(new Error("No se pudo leer el reconocimiento de Windows."));
          return;
        }
      }
    });
    child.stderr.resume();
    child.on("error", (error) => this.fail(error));
    child.on("exit", () => {
      if (this.process === child)
        this.fail(new Error("El reconocedor de Windows se cerr\xF3."));
    });
  }
  recognize(strokes, language = "es") {
    if (language !== "es" && language !== "en")
      return Promise.reject(new Error("Idioma de escritura inv\xE1lido."));
    if (!strokes.length || strokes.length > 128) return Promise.resolve([]);
    try {
      this.start();
    } catch (error) {
      return Promise.reject(error);
    }
    const id2 = ++this.serial;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(
        () => this.fail(
          new Error(
            "El reconocimiento tard\xF3 demasiado. Tu escritura se conserva."
          )
        ),
        15e3
      );
      this.pending.set(id2, { resolve, reject, timer });
      this.process.stdin.write(
        JSON.stringify({ id: id2, strokes, language }) + "\n",
        (error) => {
          if (error) this.fail(error);
        }
      );
    });
  }
  fail(error) {
    const child = this.process;
    this.process = void 0;
    child?.kill();
    for (const request of this.pending.values()) {
      clearTimeout(request.timer);
      request.reject(error);
    }
    this.pending.clear();
  }
  dispose() {
    this.disposed = true;
    this.fail(new Error("El reconocedor est\xE1 cerrado."));
  }
};

